select b.id, b.user_id, b.shop_id, b.title, b.content, b.cover, b.like_count, b.comment_count, b.status, b.create_time, b.update_time, u.nick_name as author_name, u.icon as author_icon, s.name as shop_name,
exists(select 1 from blog_like l where l.blog_id = b.id and l.user_id = #{userId}) as liked
0 as liked from blog b left join user u on u.id = b.user_id left join shop s on s.id = b.shop_id where b.status = 1 and b.user_id = #{authorId} and b.shop_id = #{shopId} order by b.create_time desc, b.id desc limit #{offset}, #{limit}

select count(*) from blog b
where b.status = 1
and b.user_id = #{authorId}
and b.shop_id = #{shopId}

select b.id, b.user_id, b.shop_id, b.title, b.content, b.cover, b.like_count, b.comment_count, b.status, b.create_time, b.update_time, u.nick_name as author_name, u.icon as author_icon, s.name as shop_name from blog b left join user u on u.id = b.user_id left join shop s on s.id = b.shop_id
and b.status = #{status} and b.user_id = #{authorId}
and (b.title like concat('%', #{keyword}, '%') or b.content like concat('%', #{keyword}, '%'))
order by b.create_time desc, b.id desc limit #{offset}, #{limit}

select count(*) from blog b

    and b.status = #{status}
    and b.user_id = #{authorId}

        and (b.title like concat('%', #{keyword}, '%') or b.content like concat('%', #{keyword}, '%'))

select b.id, b.user_id, b.create_time from blog b where b.status = 1 and b.user_id in
